def analyze_contract_text(
    text: str, role: str = "근로자"
) -> Dict[str, Any]:

    text = normalize_text(text)

    doc_info = detect_document_type(
        text
    )

    sentences = split_sentences_ko(
        text
    )

    pros = []
    cons = []

    for rule in FAVORABLE_RULES:

        evidence = find_matching_sentences(
            sentences,
            rule["patterns"],
            text,
            max_items=2
        )

        if evidence:
            pros.append({
                "title": NEUTRAL_RULE_TITLES.get(rule["title"], "관련 문구 탐지"),
                "severity": rule["severity"],
                "evidence": evidence,
                "explanation": rule["explanation"],
                "easy": rule["easy"]
            })

    for rule in UNFAVORABLE_RULES:

        evidence = find_matching_sentences(
            sentences,
            rule["patterns"],
            text,
            max_items=2
        )

        if evidence:
            cons.append({
                "title": NEUTRAL_RULE_TITLES.get(rule["title"], "관련 문구 탐지"),
                "severity": rule["severity"],
                "evidence": evidence,
                "explanation": rule["explanation"],
                "easy": rule["easy"]
            })

    pros.sort(
        key=lambda x: -x["severity"]
    )

    cons.sort(
        key=lambda x: -x["severity"]
    )

    questions = []

    if any(
        "연차" in c["title"]
        for c in cons
    ):
        questions.append(
            "연차 사용 제한 사유와 미사용 시 보상 방식이 "
            "명확한지 확인해야 합니다."
        )

    if any(
        "4대 사회보험" in c["title"]
        for c in cons
    ):
        questions.append(
            "실제 근로 형태가 4대 사회보험 적용 대상인지 "
            "확인해야 합니다."
        )

    if any(
        "휴게시간" in c["title"]
        for c in cons
    ):
        questions.append(
            "휴게시간의 시작과 종료 시간이 비어 있지 않은지 "
            "확인해야 합니다."
        )

    if any(
        "근무장소" in c["title"]
        or "업무 내용" in c["title"]
        for c in cons
    ):
        questions.append(
            "근무장소와 업무 내용을 구체적으로 적어야 합니다."
        )

    if any(
        "근로시간" in c["title"]
        or "추가수당" in c["title"]
        or "포괄임금" in c["title"]
        for c in cons
    ):
        questions.append(
            "실제 근로시간, 연장근로 여부, 추가수당 계산 방식을 "
            "확인해야 합니다."
        )

    if any(
        "주 6일" in c["title"]
        for c in cons
    ):
        questions.append(
            "주 6일 근무가 실제 근로시간과 휴일수당 문제로 "
            "이어지는지 확인해야 합니다."
        )

    if not questions:
        questions.append(
            "계약기간, 지급조건, 해지조건, 책임범위, "
            "개인정보, 비용 항목을 원문 기준으로 확인해야 합니다."
        )

    return {
        "document_type":
            doc_info["document_type"],

        "document_confidence":
            doc_info["confidence"],

        "document_scores":
            doc_info["scores"],

        "ocr_text":
            text,

        "user_role":
            role,

        "유리한_조항":
            pros,

        "불리한_조항":
            cons,

        "확인할_질문":
            questions
    }


